package com.bankease.entity;
import jakarta.persistence.*; import lombok.*; import java.math.BigDecimal; import java.time.LocalDateTime;
@Entity @Table(name="transactions",indexes={@Index(name="idx_tx_account_time",columnList="account_id,created_at"),@Index(name="idx_tx_reference",columnList="reference_code",unique=true)}) @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder
public class Transaction { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="account_id") private Account account; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private TransactionType type; @Column(nullable=false,precision=19,scale=2) private BigDecimal amount; @Column(precision=19,scale=2) private BigDecimal balanceAfter; @Column(length=24) private String relatedAccount; @Column(length=255) private String description; @Column(name="reference_code",nullable=false,unique=true,length=40) private String referenceCode; @Column(nullable=false,updatable=false) private LocalDateTime createdAt; @PrePersist void prePersist(){createdAt=LocalDateTime.now();} }